{
  "application": "poster-generation",
  "case_id": "case-science-nature-2024-neural-circuit-discovery",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A0-portrait",
    "audience": "academic-conference",
    "tone": "academic, data-forward",
    "venue": "Nature Research Conference / Neuroscience Symposium"
  },
  "brief": {
    "title": "Mapping Neural Circuit Architecture: Advances in Brain Connectivity Analysis",
    "one_liner": "A comprehensive study published in Nature (2024) reveals new principles of neural circuit organization through large-scale connectomics and functional mapping.",
    "goal": "Convey the key methodological advances, principal findings on circuit architecture, and their implications for understanding brain function to a neuroscience audience."
  },
  "sections": [
    {
      "id": "background",
      "title": "Background & Motivation",
      "objective": "Establish the scientific context: why mapping neural circuits at scale matters and what gaps existed prior to this work."
    },
    {
      "id": "methods",
      "title": "Methodology & Technical Approach",
      "objective": "Summarize the connectomics pipeline, imaging modalities, and computational analysis framework used in the study."
    },
    {
      "id": "key-findings",
      "title": "Key Findings",
      "objective": "Present the principal discoveries about neural circuit organization, including quantitative results on connectivity patterns."
    },
    {
      "id": "implications",
      "title": "Implications & Future Directions",
      "objective": "Highlight the broader significance for neuroscience, potential clinical applications, and next steps for the field."
    }
  ],
  "metrics": [
    {
      "label": "Neurons Mapped",
      "value": "~125,000",
      "context": "Total neurons reconstructed in the connectome dataset"
    },
    {
      "label": "Synaptic Connections",
      "value": "~54 million",
      "context": "Individual synapses identified and catalogued"
    },
    {
      "label": "Circuit Motifs Identified",
      "value": "37",
      "context": "Distinct recurring connectivity motifs discovered"
    },
    {
      "label": "Classification Accuracy",
      "value": "94.2%",
      "context": "Automated neuron-type classification performance"
    },
    {
      "label": "Publication",
      "value": "Nature, 2024",
      "context": "DOI: 10.1038/s41586-024-07487-w"
    }
  ]
}

